// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        vm.assume(number != 0);
        // The require gate compares msg.sender against depositorAccount, which is
        // zero in the reference contract, so only address(0) can pass the check.
        vm.prank(address(0));
        c.setL1BlockValues(
            number,
            timestamp,
            basefee,
            hash,
            sequenceNumber,
            batcherHash,
            l1FeeOverhead,
            l1FeeScalar
        );
        // Rule: a successful setL1BlockValues never alters depositorAccount.
        assertTrue(c.depositorAccount() == address(0));
    }
}
